const faqOriginal={};
document.querySelectorAll('[data-faq]').forEach(el=>{
  faqOriginal[el.dataset.faq]={q:el.querySelector('summary span').innerHTML,a:el.querySelector('.faq-answer').innerHTML};
});
const faqTranslations={};
faqTranslations.en={"washer":{"q":"How do I start a washer?","a":"<p>1. Put your laundry in the washer.<br>2. Add detergent to the washer.<br>3. Choose the programme.<br>4. Pay at the terminal.<br><strong>The washer starts automatically after payment.</strong></p>"},"capacity":{"q":"Which washer size should I choose?","a":"<p>7 kg for a small load, 14 kg for a larger load, 20 kg for very large loads or bulky items.</p><div class='faq-tip'><strong>Easy rule:</strong> do not pack the drum. You should be able to slide <strong>one hand between the top of the laundry and the top of the drum</strong>. If not, choose a larger washer.</div><p>An overloaded drum washes and spins less efficiently and may take longer to spin.</p>"},"dryer":{"q":"How do I start a dryer?","a":"<p>1. Put the laundry in the dryer.<br>2. Pay for the number of cycles you want at the terminal.<br>3. On the dryer, press the <strong>temperature suitable for your laundry</strong>.<br>Each cycle = <strong>5 minutes for €0.50</strong>.</p><div class='faq-tip'><strong>Easy rule:</strong> laundry must tumble freely. For a large load, split it between <strong>two dryers</strong> so air circulates better and drying is usually faster and more even.</div>"},"dryerTemp":{"q":"Which dryer temperature should I choose?","a":"<p><strong>Our dryers are professional and heat efficiently:</strong> always choose according to the fabric and check the care label.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · high heat</strong><span>Towels, cotton sheets, jeans, heavy cotton.</span><small>Avoid for synthetics, elastane and delicate fabrics.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · medium heat</strong><span>Everyday laundry, cotton/polyester blends, shirts, T-shirts, easy-care clothes.</span><small>Good for mixed loads if labels allow tumble drying.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · low heat</strong><span>Light synthetics, thin garments, some sportswear.</span><small>Only if the care label allows tumble drying.</small></div></div><p class='faq-source-note'>Temperatures are manufacturer reference values for this family of professional IPSO 30 lb dryers; the exact setting may vary slightly with machine programming.</p>"},"dryerBall":{"q":"Laundry has balled up in the dryer: what should I do?","a":"<p>You can <strong>open the door during the cycle</strong>: the dryer stops. Untangle and spread the laundry, then close the door again.</p><div class='faq-tip'><strong>To restart:</strong> press your chosen temperature again — <strong>HIGH, PERM PRESS / MEDIUM or LOW</strong>. The dryer restarts automatically.</div><p>This is especially useful for sheets, duvet covers and other large items.</p>"},"ironer":{"q":"How do I use the flatwork ironer?","a":"<p>Pay at the terminal, then allow about <strong>3–4 minutes to heat up</strong>. It starts automatically. Price: <strong>€2.00 / 6 min</strong>.</p><p class='faq-warning'><strong>Only for flat linen suitable for heat.</strong> No buttons, zips, metal/plastic parts or heat-sensitive synthetic fabrics: these can damage the laundry and the machine.</p><div class='faq-tip'><strong>Before feeding it in:</strong> run your hand over the item. If you feel anything hard, thick or a fastening, <strong>do not put it through the ironer</strong>.</div>"},"pets":{"q":"Where should I wash animal textiles?","a":"<p>Use only the machines clearly marked <strong>ANIMAUX / PETS</strong> for blankets, beds and other animal textiles. They are available in <strong>7 kg and 14 kg</strong>.</p>"},"pay":{"q":"How do I pay?","a":"<p>At the terminal, <strong>select your washer or dryer</strong>, then pay with coins, notes, contactless card or smartphone. The screen guides you step by step.</p><div class='faq-tip'><strong>After payment:</strong> if you need an invoice, look at the screen immediately: the 4-character code is shown for only about 5 seconds.</div>"},"code":{"q":"What is the code shown after payment for?","a":"<p>A <strong>4-character code</strong> appears for about <strong>5 seconds</strong> immediately after payment. Note it down if you want an invoice. It can be used for <strong>24 hours</strong>.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Get my invoice on WiLine ↗</a>"},"availability":{"q":"How can I see if a machine is free?","a":"<p>Open WiLine to see which machines are available and which are running.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>View machines on WiLine ↗</a>"},"notify":{"q":"Can I be notified when my cycle is finished?","a":"<p><strong>Yes.</strong><br>1. Open WiLine.<br>2. Find your machine.<br>3. Tap the <strong>small bell to the right of your machine</strong>.<br>4. You will receive a notification when the cycle ends.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Open WiLine and activate the bell ↗</a>"},"loyalty":{"q":"How does the loyalty card work?","a":"<p>Your first card is free: <strong>€40 paid = €40 credit</strong> + 1 detergent sachet. Later top-ups add bonus credit depending on the amount loaded.</p>"},"ownDetergent":{"q":"Can I use my own detergent?","a":"<p><strong>Yes, you choose.</strong> Bring your own detergent if you prefer your usual brand or scent. Or buy products on site: <strong>Eco, Sensitive Skin and Premium detergent, fabric softeners, disinfectant and oxygen stain remover.</strong></p><div class='faq-tip'><strong>Simple:</strong> use your usual product or choose one here.</div>"},"products":{"q":"Which products are available?","a":"<p><strong>Detergents:</strong> Eco, Sensitive Skin and Premium.<br><strong>Fabric softeners:</strong> scented or sensitive skin.<br><strong>Other:</strong> disinfectant and oxygen stain remover.</p>"},"cowork":{"q":"Can I work while my cycle is running?","a":"<p>Yes. A large table, seats and power outlets are available. Activate the WiLine bell and work until your cycle is finished.</p>"},"parcels":{"q":"Are Vinted Go and bpost available?","a":"<p>Yes. You can drop off or collect Vinted Go and bpost / bbox parcels during your visit.</p>"},"basketsWater":{"q":"Are laundry baskets and softened water available?","a":"<p>Yes. Laundry baskets are available on site and the laundromat uses softened water.</p>"},"pro":{"q":"I am a professional. Can I contact you?","a":"<p>Yes. For regular visits, large volumes or specific needs, use the form and choose <strong>“Professional / rates”</strong>.</p><a class='faq-link' href='#contact'>Contact POP’n WASH ↓</a>"},"problem":{"q":"I have a problem with a machine. What should I do?","a":"<p>Call or WhatsApp <strong>+32 486 999 251</strong>, or use the contact form.</p>"},"suggestion":{"q":"I have an improvement idea. How can I send it?","a":"<p>Choose <strong>“Suggestion / improvement idea”</strong> in the form, or use the suggestion box in the laundromat. All ideas are welcome.</p><a class='faq-link' href='#contact'>Send an idea ↓</a>"},"hours":{"q":"What are the opening hours and address?","a":"<p><strong>7 days a week · 07:00–22:00</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Open directions ↗</a>"},"parking":{"q":"Where can I park?","a":"<p>You get 30 minutes free on-street after registering your licence plate, with several nearby parking options as well.</p>"}};

faqTranslations.nl={"washer":{"q":"Hoe start ik een wasmachine?","a":"<p>1. Doe uw was in de machine.<br>2. Voeg wasmiddel toe in de wasmachine.<br>3. Kies het programma.<br>4. Betaal aan de centrale.<br><strong>De wasmachine start automatisch na betaling.</strong></p>"},"capacity":{"q":"Welke machinegrootte kies ik?","a":"<p>7 kg voor een kleine was, 14 kg voor een grotere lading, 20 kg voor zeer grote volumes of grote stukken.</p><div class='faq-tip'><strong>Eenvoudige regel:</strong> prop de trommel niet vol. U moet <strong>één hand tussen de was en de bovenkant van de trommel</strong> kunnen schuiven. Lukt dat niet, kies een grotere machine.</div><p>Een te volle trommel wast en centrifugeert minder goed en kan langer centrifugeren.</p>"},"dryer":{"q":"Hoe start ik een droger?","a":"<p>1. Doe de was in de droger.<br>2. Betaal het gewenste aantal cycli aan de centrale.<br>3. Druk op de droger op de <strong>juiste temperatuur voor uw was</strong>.<br>Elke cyclus = <strong>5 minuten voor €0,50</strong>.</p><div class='faq-tip'><strong>Eenvoudige regel:</strong> de was moet vrij kunnen vallen en draaien. Verdeel een grote lading over <strong>twee drogers</strong> voor betere luchtcirculatie en meestal sneller, gelijkmatiger drogen.</div>"},"dryerTemp":{"q":"Welke temperatuur kies ik op de droger?","a":"<p><strong>Onze drogers zijn professioneel en verwarmen krachtig:</strong> kies volgens het textiel en controleer het waslabel.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · hoge warmte</strong><span>Handdoeken, katoenen lakens, jeans, dik katoen.</span><small>Niet voor synthetische stoffen, elastaan of delicate stoffen.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · middelhoge warmte</strong><span>Dagelijkse was, katoen/polyester, hemden, T-shirts, easy-care kleding.</span><small>Voor gemengde ladingen als het label drogen toelaat.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · zachte warmte</strong><span>Lichte synthetische stoffen, fijne kleding, sommige sportkleding.</span><small>Alleen als het label drogen toelaat.</small></div></div><p class='faq-source-note'>Fabrikant-referentiewaarden voor deze familie professionele IPSO 30 lb-drogers; de exacte instelling kan licht verschillen door programmering.</p>"},"dryerBall":{"q":"De was zit in een bol tijdens het drogen: wat doe ik?","a":"<p>U kunt <strong>de deur tijdens de cyclus openen</strong>: de droger stopt. Maak de was los en verdeel ze in de trommel, sluit daarna de deur.</p><div class='faq-tip'><strong>Opnieuw starten:</strong> druk opnieuw op de gewenste temperatuur — <strong>HIGH, PERM PRESS / MEDIUM of LOW</strong>. De droger start automatisch.</div><p>Handig voor lakens, dekbedovertrekken en grote stukken.</p>"},"ironer":{"q":"Hoe gebruik ik de mangel?","a":"<p>Betaal aan de centrale en wacht ongeveer <strong>3–4 minuten opwarming</strong>. De mangel start automatisch. Tarief: <strong>€2,00 / 6 min</strong>.</p><p class='faq-warning'><strong>Alleen vlak wasgoed dat hitte verdraagt.</strong> Geen knopen, ritsen, metalen/plastic delen of hittegevoelige synthetische stoffen.</p><div class='faq-tip'><strong>Controle:</strong> ga met uw hand over het textiel. Voelt u iets hard, dik of een sluiting, <strong>stop het dan niet in de mangel</strong>.</div>"},"pets":{"q":"Waar was ik dierentextiel?","a":"<p>Gebruik alleen de machines met <strong>ANIMAUX / PETS</strong> voor dekens, manden en ander dierentextiel. Beschikbaar in <strong>7 kg en 14 kg</strong>.</p>"},"pay":{"q":"Hoe betaal ik?","a":"<p>Kies aan de centrale <strong>uw wasmachine of droger</strong> en betaal met munten, biljetten, contactloze kaart of smartphone. Het scherm begeleidt u.</p><div class='faq-tip'><strong>Na betaling:</strong> voor een factuur kijkt u meteen naar het scherm. De 4-teken code verschijnt ongeveer 5 seconden.</div>"},"code":{"q":"Waarvoor dient de code na betaling?","a":"<p>Een <strong>code van 4 tekens</strong> verschijnt ongeveer <strong>5 seconden</strong> na betaling. Noteer hem voor uw factuur. Hij is <strong>24 uur</strong> bruikbaar.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Factuur ophalen op WiLine ↗</a>"},"availability":{"q":"Hoe zie ik of een machine vrij is?","a":"<p>Open WiLine: u ziet meteen welke machines vrij zijn en welke draaien.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Machines bekijken op WiLine ↗</a>"},"notify":{"q":"Kan ik een melding krijgen wanneer mijn cyclus klaar is?","a":"<p><strong>Ja.</strong><br>1. Open WiLine.<br>2. Zoek uw machine.<br>3. Klik op het <strong>kleine belletje rechts van uw machine</strong>.<br>4. U krijgt een melding wanneer de cyclus klaar is.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>WiLine openen en bel activeren ↗</a>"},"loyalty":{"q":"Hoe werkt de klantenkaart?","a":"<p>De eerste kaart is gratis: <strong>€40 betaald = €40 tegoed</strong> + 1 zakje wasmiddel. Bij volgende herladingen krijgt u extra tegoed volgens het geladen bedrag.</p>"},"ownDetergent":{"q":"Mag ik mijn eigen wasmiddel gebruiken?","a":"<p><strong>Ja, u kiest.</strong> Neem uw eigen wasmiddel mee als u uw merk of geur verkiest. Of koop ter plaatse: <strong>Eco, Gevoelige huid, Premium, wasverzachters, ontsmettingsmiddel en zuurstofvlekkenmiddel.</strong></p>"},"products":{"q":"Welke producten zijn beschikbaar?","a":"<p><strong>Wasmiddelen:</strong> Eco, Gevoelige huid en Premium.<br><strong>Wasverzachters:</strong> geparfumeerd of gevoelige huid.<br><strong>Andere:</strong> ontsmettingsmiddel en zuurstofvlekkenmiddel.</p>"},"cowork":{"q":"Kan ik werken tijdens mijn cyclus?","a":"<p>Ja. Er is een grote tafel met zitplaatsen en stopcontacten. Activeer het WiLine-belletje en werk rustig tot uw cyclus klaar is.</p>"},"parcels":{"q":"Zijn Vinted Go en bpost aanwezig?","a":"<p>Ja. U kunt tijdens uw bezoek Vinted Go- en bpost/bbox-pakketten afgeven of ophalen.</p>"},"basketsWater":{"q":"Zijn er wasmanden en onthard water?","a":"<p>Ja. Er zijn wasmanden beschikbaar en de wasserette gebruikt onthard water.</p>"},"pro":{"q":"Ik ben professional. Kan ik contact opnemen?","a":"<p>Ja. Voor regelmatige bezoeken, grote volumes of speciale behoeften kiest u in het formulier <strong>“Professioneel / tarieven”</strong>.</p><a class='faq-link' href='#contact'>POP’n WASH contacteren ↓</a>"},"problem":{"q":"Ik heb een probleem met een machine. Wat nu?","a":"<p>Bel of WhatsApp <strong>+32 486 999 251</strong>, of gebruik het contactformulier.</p>"},"suggestion":{"q":"Ik heb een verbeteridee. Hoe geef ik het door?","a":"<p>Kies <strong>“Suggestie / verbeteridee”</strong> in het formulier of gebruik de ideeënbox in de wasserette.</p><a class='faq-link' href='#contact'>Idee versturen ↓</a>"},"hours":{"q":"Wat zijn de openingsuren en het adres?","a":"<p><strong>7/7 · 07u–22u</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Route openen ↗</a>"},"parking":{"q":"Waar kan ik parkeren?","a":"<p>U krijgt 30 minuten gratis op straat na registratie van uw nummerplaat, plus verschillende parkeeropties in de buurt.</p>"}};
faqTranslations.de={"washer":{"q":"Wie starte ich eine Waschmaschine?","a":"<p>1. Wäsche einlegen.<br>2. Waschmittel in die Waschmaschine geben.<br>3. Programm wählen.<br>4. An der Zentrale bezahlen.<br><strong>Die Waschmaschine startet nach der Zahlung automatisch.</strong></p>"},"capacity":{"q":"Welche Maschinengröße soll ich wählen?","a":"<p>7 kg für kleine, 14 kg für größere, 20 kg für sehr große Wäschemengen oder sperrige Teile.</p><div class='faq-tip'><strong>Einfache Regel:</strong> nicht stopfen. Zwischen Wäsche und Trommeloberkante sollte <strong>eine Hand Platz</strong> bleiben. Sonst eine größere Maschine wählen.</div><p>Überfüllung verschlechtert Waschen und Schleudern und kann die Schleuderzeit verlängern.</p>"},"dryer":{"q":"Wie starte ich einen Trockner?","a":"<p>1. Wäsche einlegen.<br>2. Gewünschte Zyklen an der Zentrale bezahlen.<br>3. Am Trockner die <strong>passende Temperatur</strong> drücken.<br>Jeder Zyklus = <strong>5 Minuten für 0,50 €</strong>.</p><div class='faq-tip'><strong>Einfache Regel:</strong> die Wäsche muss frei fallen und drehen können. Große Mengen auf <strong>zwei Trockner</strong> verteilen; so trocknet sie meist schneller und gleichmäßiger.</div>"},"dryerTemp":{"q":"Welche Trocknertemperatur soll ich wählen?","a":"<p><strong>Unsere Trockner sind professionell und heizen kräftig:</strong> nach Textil wählen und Pflegeetikett beachten.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · hohe Hitze</strong><span>Handtücher, Baumwollbettwäsche, Jeans, schwere Baumwolle.</span><small>Nicht für Synthetik, Elasthan oder empfindliche Stoffe.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · mittlere Hitze</strong><span>Alltagswäsche, Baumwolle/Polyester, Hemden, T-Shirts, pflegeleichte Kleidung.</span><small>Für Mischwäsche, wenn das Etikett Trocknen erlaubt.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · geringe Hitze</strong><span>Leichte Synthetik, dünne Kleidung, manche Sportkleidung.</span><small>Nur wenn das Pflegeetikett Trocknen erlaubt.</small></div></div><p class='faq-source-note'>Hersteller-Richtwerte für diese Familie professioneller IPSO-30-lb-Trockner; die genaue Einstellung kann je nach Programmierung leicht abweichen.</p>"},"dryerBall":{"q":"Die Wäsche hat sich beim Trocknen zusammengeballt – was tun?","a":"<p>Sie können <strong>die Tür während des Zyklus öffnen</strong>; der Trockner stoppt. Wäsche lösen und verteilen, Tür wieder schließen.</p><div class='faq-tip'><strong>Neustart:</strong> gewünschte Temperatur erneut drücken — <strong>HIGH, PERM PRESS / MEDIUM oder LOW</strong>. Der Trockner startet automatisch.</div><p>Besonders sinnvoll bei Bettlaken, Bezügen und großen Teilen.</p>"},"ironer":{"q":"Wie benutze ich die Mangel?","a":"<p>An der Zentrale bezahlen und etwa <strong>3–4 Minuten Aufheizzeit</strong> warten. Sie startet automatisch. Preis: <strong>2,00 € / 6 Min.</strong></p><p class='faq-warning'><strong>Nur für hitzegeeignete Flachwäsche.</strong> Keine Knöpfe, Reißverschlüsse, Metall-/Kunststoffteile oder hitzeempfindliche Synthetik.</p><div class='faq-tip'><strong>Vorher prüfen:</strong> mit der Hand über das Textil fahren. Bei harten, dicken Teilen oder Verschlüssen <strong>nicht mangeln</strong>.</div>"},"pets":{"q":"Wo wasche ich Tiertextilien?","a":"<p>Nur Maschinen mit Kennzeichnung <strong>ANIMAUX / PETS</strong> für Decken, Körbe und Tiertextilien benutzen. Verfügbar in <strong>7 kg und 14 kg</strong>.</p>"},"pay":{"q":"Wie bezahle ich?","a":"<p>An der Zentrale <strong>Waschmaschine oder Trockner wählen</strong> und mit Münzen, Scheinen, kontaktloser Karte oder Smartphone zahlen. Das Display führt Sie.</p><div class='faq-tip'><strong>Nach Zahlung:</strong> für eine Rechnung sofort auf das Display schauen. Der 4-Zeichen-Code erscheint nur etwa 5 Sekunden.</div>"},"code":{"q":"Wozu dient der Code nach der Zahlung?","a":"<p>Ein <strong>4-Zeichen-Code</strong> erscheint etwa <strong>5 Sekunden</strong> nach der Zahlung. Für die Rechnung notieren; er ist <strong>24 Stunden</strong> nutzbar.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Rechnung in WiLine abrufen ↗</a>"},"availability":{"q":"Wie sehe ich, ob eine Maschine frei ist?","a":"<p>WiLine öffnen: dort sehen Sie freie und laufende Maschinen.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Maschinen in WiLine ansehen ↗</a>"},"notify":{"q":"Kann ich am Zyklusende benachrichtigt werden?","a":"<p><strong>Ja.</strong><br>1. WiLine öffnen.<br>2. Ihre Maschine suchen.<br>3. Auf die <strong>kleine Glocke rechts neben der Maschine</strong> klicken.<br>4. Am Ende erhalten Sie eine Benachrichtigung.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>WiLine öffnen und Glocke aktivieren ↗</a>"},"loyalty":{"q":"Wie funktioniert die Treuekarte?","a":"<p>Die erste Karte ist gratis: <strong>40 € bezahlt = 40 € Guthaben</strong> + 1 Waschmittelbeutel. Weitere Aufladungen bringen je nach Betrag Bonusguthaben.</p>"},"ownDetergent":{"q":"Kann ich mein eigenes Waschmittel verwenden?","a":"<p><strong>Ja, Sie haben die Wahl.</strong> Eigenes Waschmittel für Ihre bevorzugte Marke oder Duftnote mitbringen oder vor Ort kaufen: <strong>Eco, Sensitive, Premium, Weichspüler, Desinfektion und Oxy-Fleckentferner.</strong></p>"},"products":{"q":"Welche Produkte gibt es?","a":"<p><strong>Waschmittel:</strong> Eco, Sensitive und Premium.<br><strong>Weichspüler:</strong> parfümiert oder Sensitive.<br><strong>Weitere:</strong> Desinfektion und Oxy-Fleckentferner.</p>"},"cowork":{"q":"Kann ich während des Zyklus arbeiten?","a":"<p>Ja. Großer Tisch, Sitzplätze und Steckdosen sind vorhanden. WiLine-Glocke aktivieren und bis Zyklusende arbeiten.</p>"},"parcels":{"q":"Gibt es Vinted Go und bpost?","a":"<p>Ja. Vinted Go- und bpost/bbox-Pakete können während des Besuchs abgegeben oder abgeholt werden.</p>"},"basketsWater":{"q":"Gibt es Wäschekörbe und enthärtetes Wasser?","a":"<p>Ja. Wäschekörbe stehen bereit und die Anlage nutzt enthärtetes Wasser.</p>"},"pro":{"q":"Ich bin Gewerbekunde. Kann ich Sie kontaktieren?","a":"<p>Ja. Für regelmäßige Nutzung, große Mengen oder spezielle Bedürfnisse im Formular <strong>„Gewerbe / Tarife“</strong> wählen.</p><a class='faq-link' href='#contact'>POP’n WASH kontaktieren ↓</a>"},"problem":{"q":"Problem mit einer Maschine – was tun?","a":"<p>Anrufen oder WhatsApp an <strong>+32 486 999 251</strong>, oder Kontaktformular nutzen.</p>"},"suggestion":{"q":"Ich habe eine Verbesserungsidee. Wie sende ich sie?","a":"<p>Im Formular <strong>„Vorschlag / Verbesserungsidee“</strong> wählen oder die Ideenbox im Waschsalon nutzen.</p><a class='faq-link' href='#contact'>Idee senden ↓</a>"},"hours":{"q":"Öffnungszeiten und Adresse?","a":"<p><strong>7 Tage · 07–22 Uhr</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Route öffnen ↗</a>"},"parking":{"q":"Wo kann ich parken?","a":"<p>30 Minuten kostenlos an der Straße nach Kennzeichenregistrierung; außerdem mehrere Parkmöglichkeiten in der Nähe.</p>"}};
faqTranslations.it={"washer":{"q":"Come avvio una lavatrice?","a":"<p>1. Metti il bucato nella lavatrice.<br>2. Aggiungi il detersivo nella lavatrice.<br>3. Scegli il programma.<br>4. Paga alla centrale.<br><strong>La lavatrice parte automaticamente dopo il pagamento.</strong></p>"},"capacity":{"q":"Quale capacità scegliere?","a":"<p>7 kg per un piccolo bucato, 14 kg per un volume maggiore, 20 kg per volumi molto grandi o pezzi voluminosi.</p><div class='faq-tip'><strong>Regola semplice:</strong> non comprimere il bucato. Devi poter inserire <strong>una mano tra il bucato e la parte alta del cestello</strong>. Altrimenti scegli una macchina più grande.</div><p>Una macchina troppo piena lava e centrifuga peggio e può impiegare più tempo.</p>"},"dryer":{"q":"Come avvio un’asciugatrice?","a":"<p>1. Metti il bucato nell’asciugatrice.<br>2. Paga alla centrale il numero di cicli desiderato.<br>3. Premi sull’asciugatrice la <strong>temperatura adatta al tessuto</strong>.<br>Ogni ciclo = <strong>5 minuti per 0,50 €</strong>.</p><div class='faq-tip'><strong>Regola semplice:</strong> il bucato deve cadere e girare liberamente. Per grandi volumi dividilo tra <strong>due asciugatrici</strong>.</div>"},"dryerTemp":{"q":"Quale temperatura scegliere?","a":"<p><strong>Le nostre asciugatrici sono professionali e scaldano in modo efficace:</strong> scegli sempre in base al tessuto e controlla l’etichetta.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · alta</strong><span>Asciugamani, lenzuola in cotone, jeans, cotone spesso.</span><small>Evitare per sintetici, elastan e delicati.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · media</strong><span>Bucato quotidiano, misto cotone/poliestere, camicie, T-shirt.</span><small>Per carichi misti se l’etichetta consente l’asciugatrice.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · bassa</strong><span>Sintetici leggeri, capi fini, alcuni capi sportivi.</span><small>Solo se l’etichetta consente l’asciugatrice.</small></div></div><p class='faq-source-note'>Temperature indicative del costruttore per questa famiglia di asciugatrici professionali IPSO 30 lb; possono variare leggermente secondo la programmazione.</p>"},"dryerBall":{"q":"Il bucato si è appallottolato: cosa fare?","a":"<p>Puoi <strong>aprire la porta durante il ciclo</strong>: l’asciugatrice si ferma. Sciogli e distribuisci il bucato, poi richiudi.</p><div class='faq-tip'><strong>Per ripartire:</strong> premi di nuovo la temperatura scelta — <strong>HIGH, PERM PRESS / MEDIUM o LOW</strong>. Riparte automaticamente.</div>"},"ironer":{"q":"Come usare la calandra?","a":"<p>Paga alla centrale, poi attendi circa <strong>3–4 minuti di riscaldamento</strong>. Parte automaticamente. Tariffa: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Solo biancheria piana adatta al calore.</strong> Niente bottoni, zip, parti metalliche/plastiche o sintetici sensibili al calore.</p><div class='faq-tip'><strong>Prima:</strong> passa la mano sul tessuto. Se senti qualcosa di duro, spesso o una chiusura, <strong>non inserirlo nella calandra</strong>.</div>"},"pets":{"q":"Dove lavare i tessili degli animali?","a":"<p>Usa solo le macchine marcate <strong>ANIMAUX / PETS</strong> per coperte, cucce e altri tessili animali. Disponibili in <strong>7 kg e 14 kg</strong>.</p>"},"pay":{"q":"Come pagare?","a":"<p>Alla centrale <strong>seleziona lavatrice o asciugatrice</strong>, poi paga con monete, banconote, carta contactless o smartphone.</p><div class='faq-tip'><strong>Dopo il pagamento:</strong> se vuoi una fattura guarda subito lo schermo: il codice di 4 caratteri resta visibile circa 5 secondi.</div>"},"code":{"q":"A cosa serve il codice dopo il pagamento?","a":"<p>Un <strong>codice di 4 caratteri</strong> appare per circa <strong>5 secondi</strong> dopo il pagamento. Annotalo per la fattura. È utilizzabile per <strong>24 ore</strong>.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Recupera la fattura su WiLine ↗</a>"},"availability":{"q":"Come vedo se una macchina è libera?","a":"<p>Apri WiLine: vedi subito le macchine libere e quelle in funzione.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Vedi le macchine su WiLine ↗</a>"},"notify":{"q":"Posso ricevere una notifica a fine ciclo?","a":"<p><strong>Sì.</strong><br>1. Apri WiLine.<br>2. Trova la tua macchina.<br>3. Premi la <strong>piccola campana a destra della macchina</strong>.<br>4. Riceverai una notifica a fine ciclo.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Apri WiLine e attiva la campana ↗</a>"},"loyalty":{"q":"Come funziona la carta fedeltà?","a":"<p>La prima carta è gratuita: <strong>40 € pagati = 40 € di credito</strong> + 1 dose di detersivo. Le ricariche successive danno credito extra in base all’importo.</p>"},"ownDetergent":{"q":"Posso usare il mio detersivo?","a":"<p><strong>Sì, scegli tu.</strong> Porta il tuo detersivo se preferisci marca o profumo abituale, oppure usa i prodotti disponibili: <strong>Eco, Pelli sensibili, Premium, ammorbidenti, disinfettante e smacchiatore ossigenato.</strong></p>"},"products":{"q":"Quali prodotti sono disponibili?","a":"<p><strong>Detersivi:</strong> Eco, Pelli sensibili e Premium.<br><strong>Ammorbidenti:</strong> profumato o pelli sensibili.<br><strong>Altro:</strong> disinfettante e smacchiatore ossigenato.</p>"},"cowork":{"q":"Posso lavorare durante il ciclo?","a":"<p>Sì. Sono disponibili grande tavolo, sedute e prese elettriche. Attiva la campana WiLine e lavora fino alla fine del ciclo.</p>"},"parcels":{"q":"Ci sono Vinted Go e bpost?","a":"<p>Sì. Puoi depositare o ritirare pacchi Vinted Go e bpost / bbox durante la visita.</p>"},"basketsWater":{"q":"Ci sono cesti e acqua addolcita?","a":"<p>Sì. Sono disponibili cesti per il bucato e la lavanderia usa acqua addolcita.</p>"},"pro":{"q":"Sono un professionista: posso contattarvi?","a":"<p>Sì. Per visite regolari, grandi volumi o esigenze specifiche scegli <strong>“Professionale / tariffe”</strong> nel modulo.</p><a class='faq-link' href='#contact'>Contatta POP’n WASH ↓</a>"},"problem":{"q":"Ho un problema con una macchina: cosa faccio?","a":"<p>Chiama o invia WhatsApp al <strong>+32 486 999 251</strong>, oppure usa il modulo.</p>"},"suggestion":{"q":"Ho un’idea di miglioramento: come inviarla?","a":"<p>Scegli <strong>“Suggerimento / idea”</strong> nel modulo oppure usa la cassetta delle idee in lavanderia.</p><a class='faq-link' href='#contact'>Invia un’idea ↓</a>"},"hours":{"q":"Quali sono orari e indirizzo?","a":"<p><strong>7/7 · 07:00–22:00</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Apri indicazioni ↗</a>"},"parking":{"q":"Dove posso parcheggiare?","a":"<p>30 minuti gratuiti in strada dopo la registrazione della targa, più varie possibilità di parcheggio nelle vicinanze.</p>"}};

faqTranslations.es={"washer":{"q":"¿Cómo pongo en marcha una lavadora?","a":"<p>1. Mete la ropa en la lavadora.<br>2. Añade el detergente en la lavadora.<br>3. Elige el programa.<br>4. Paga en la central.<br><strong>La lavadora arranca automáticamente después del pago.</strong></p>"},"capacity":{"q":"¿Qué tamaño de lavadora debo elegir?","a":"<p>7 kg para una colada pequeña, 14 kg para más volumen y 20 kg para cargas muy grandes o piezas voluminosas.</p><div class='faq-tip'><strong>Regla fácil:</strong> no aprietes la ropa. Debe caber <strong>una mano entre la parte superior de la ropa y la parte superior del tambor</strong>. Si no cabe, elige una máquina mayor.</div><p>Una máquina demasiado llena lava y centrifuga peor y puede tardar más en centrifugar.</p>"},"dryer":{"q":"¿Cómo pongo en marcha una secadora?","a":"<p>1. Mete la ropa en la secadora.<br>2. Paga en la central el número de ciclos que quieras.<br>3. En la secadora, pulsa la <strong>temperatura adecuada para tu ropa</strong>.<br>Cada ciclo = <strong>5 minutos por 0,50 €</strong>.</p><div class='faq-tip'><strong>Regla fácil:</strong> la ropa debe caer y girar libremente. Para una carga grande, repártela entre <strong>dos secadoras</strong> para que circule mejor el aire.</div>"},"dryerTemp":{"q":"¿Qué temperatura debo elegir en la secadora?","a":"<p><strong>Nuestras secadoras son profesionales y calientan con eficacia:</strong> elige siempre según el tejido y revisa la etiqueta de cuidado.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · calor alto</strong><span>Toallas, sábanas de algodón, vaqueros, algodón grueso.</span><small>Evitar en sintéticos, elastano y tejidos delicados.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · calor medio</strong><span>Ropa cotidiana, mezclas algodón/poliéster, camisas, camisetas.</span><small>Buena opción para cargas mixtas si la etiqueta permite secadora.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · calor suave</strong><span>Sintéticos ligeros, prendas finas, algunas prendas deportivas.</span><small>Solo si la etiqueta permite secadora.</small></div></div><p class='faq-source-note'>Son valores de referencia del fabricante para esta familia de secadoras profesionales IPSO de 30 lb; el ajuste exacto puede variar ligeramente según la programación.</p>"},"dryerBall":{"q":"La ropa se ha hecho una bola durante el secado: ¿qué hago?","a":"<p>Puedes <strong>abrir la puerta durante el ciclo</strong>: la secadora se detiene. Deshaz la bola, reparte la ropa y vuelve a cerrar la puerta.</p><div class='faq-tip'><strong>Para reiniciar:</strong> vuelve a pulsar la temperatura deseada — <strong>HIGH, PERM PRESS / MEDIUM o LOW</strong>. La secadora arranca de nuevo automáticamente.</div>"},"ironer":{"q":"¿Cómo uso la calandra?","a":"<p>Paga en la central y espera unos <strong>3–4 minutos de calentamiento</strong>. Arranca automáticamente. Precio: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Solo para ropa plana apta para calor.</strong> No introduzcas botones, cremalleras, piezas metálicas/plásticas ni sintéticos sensibles al calor.</p><div class='faq-tip'><strong>Antes:</strong> pasa la mano por la prenda. Si notas algo duro, grueso o un cierre, <strong>no lo introduzcas en la calandra</strong>.</div>"},"pets":{"q":"¿Dónde lavo los textiles de animales?","a":"<p>Usa solo las máquinas marcadas <strong>ANIMAUX / PETS</strong> para mantas, camas y otros textiles de animales. Disponibles en <strong>7 kg y 14 kg</strong>.</p>"},"pay":{"q":"¿Cómo pago?","a":"<p>En la central, <strong>selecciona tu lavadora o secadora</strong> y paga con monedas, billetes, tarjeta sin contacto o smartphone. La pantalla te guía paso a paso.</p><div class='faq-tip'><strong>Después del pago:</strong> si necesitas factura, mira la pantalla enseguida: el código de 4 caracteres aparece solo unos 5 segundos.</div>"},"code":{"q":"¿Para qué sirve el código que aparece tras el pago?","a":"<p>Un <strong>código de 4 caracteres</strong> aparece durante unos <strong>5 segundos</strong> justo después del pago. Anótalo si quieres una factura. Se puede usar durante <strong>24 horas</strong>.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Recuperar mi factura en WiLine ↗</a>"},"availability":{"q":"¿Cómo veo si una máquina está libre?","a":"<p>Abre WiLine: verás directamente qué máquinas están libres y cuáles están funcionando.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Ver máquinas en WiLine ↗</a>"},"notify":{"q":"¿Puedo recibir un aviso cuando termine mi ciclo?","a":"<p><strong>Sí.</strong><br>1. Abre WiLine.<br>2. Busca tu máquina.<br>3. Pulsa la <strong>pequeña campana a la derecha de tu máquina</strong>.<br>4. Recibirás una notificación cuando termine el ciclo.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Abrir WiLine y activar la campana ↗</a>"},"loyalty":{"q":"¿Cómo funciona la tarjeta de fidelidad?","a":"<p>La primera tarjeta es gratuita: <strong>40 € pagados = 40 € de crédito</strong> + 1 dosis de detergente. Las recargas siguientes añaden crédito extra según el importe.</p>"},"ownDetergent":{"q":"¿Puedo usar mi propio detergente?","a":"<p><strong>Sí, tú eliges.</strong> Trae tu detergente si prefieres tu marca o aroma habitual. También puedes comprar aquí: <strong>Eco, Piel sensible, Premium, suavizantes, desinfectante y quitamanchas con oxígeno.</strong></p>"},"products":{"q":"¿Qué productos hay disponibles?","a":"<p><strong>Detergentes:</strong> Eco, Piel sensible y Premium.<br><strong>Suavizantes:</strong> perfumado o piel sensible.<br><strong>Otros:</strong> desinfectante y quitamanchas con oxígeno.</p>"},"cowork":{"q":"¿Puedo trabajar durante mi ciclo?","a":"<p>Sí. Hay una mesa grande, asientos y enchufes. Activa la campana de WiLine y trabaja tranquilamente hasta el final.</p>"},"parcels":{"q":"¿Hay Vinted Go y bpost?","a":"<p>Sí. Puedes dejar o recoger paquetes de Vinted Go y bpost / bbox durante tu visita.</p>"},"basketsWater":{"q":"¿Hay cestas para la ropa y agua descalcificada?","a":"<p>Sí. Hay cestas disponibles y la lavandería utiliza agua descalcificada.</p>"},"pro":{"q":"Soy profesional, ¿puedo contactar con vosotros?","a":"<p>Sí. Para visitas regulares, grandes volúmenes o necesidades específicas, usa el formulario y elige <strong>“Profesional / tarifas”</strong>.</p><a class='faq-link' href='#contact'>Contactar con POP’n WASH ↓</a>"},"problem":{"q":"Tengo un problema con una máquina, ¿qué hago?","a":"<p>Llama o envía WhatsApp al <strong>+32 486 999 251</strong>, o usa el formulario de contacto.</p>"},"suggestion":{"q":"Tengo una idea de mejora, ¿cómo la envío?","a":"<p>Elige <strong>“Sugerencia / idea de mejora”</strong> en el formulario o usa el buzón de ideas de la lavandería.</p><a class='faq-link' href='#contact'>Enviar una idea ↓</a>"},"hours":{"q":"¿Cuáles son los horarios y la dirección?","a":"<p><strong>7/7 · 07:00–22:00</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Abrir indicaciones ↗</a>"},"parking":{"q":"¿Dónde puedo aparcar?","a":"<p>Tienes 30 minutos gratis en la calle tras registrar la matrícula, además de varias opciones de aparcamiento cercanas.</p>"}};
faqTranslations.pt={"washer":{"q":"Como iniciar uma máquina de lavar?","a":"<p>1. Coloque a roupa na máquina.<br>2. Adicione o detergente na máquina.<br>3. Escolha o programa.<br>4. Pague na central.<br><strong>A máquina inicia automaticamente após o pagamento.</strong></p>"},"capacity":{"q":"Que tamanho de máquina escolher?","a":"<p>7 kg para uma lavagem pequena, 14 kg para mais volume e 20 kg para cargas muito grandes ou peças volumosas.</p><div class='faq-tip'><strong>Regra simples:</strong> não comprima a roupa. Deve caber <strong>uma mão entre o topo da roupa e o topo do tambor</strong>. Se não couber, escolha uma máquina maior.</div><p>Uma máquina demasiado cheia lava e centrifuga pior e pode demorar mais a centrifugar.</p>"},"dryer":{"q":"Como iniciar um secador?","a":"<p>1. Coloque a roupa no secador.<br>2. Pague na central o número de ciclos desejado.<br>3. No secador, prima a <strong>temperatura adequada à roupa</strong>.<br>Cada ciclo = <strong>5 minutos por 0,50 €</strong>.</p><div class='faq-tip'><strong>Regra simples:</strong> a roupa deve cair e rodar livremente. Para uma carga grande, divida-a por <strong>dois secadores</strong>.</div>"},"dryerTemp":{"q":"Que temperatura escolher no secador?","a":"<p><strong>Os nossos secadores são profissionais e aquecem eficazmente:</strong> escolha sempre de acordo com o tecido e confirme a etiqueta.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · temperatura alta</strong><span>Toalhas, lençóis de algodão, ganga, algodão grosso.</span><small>Evitar em sintéticos, elastano e tecidos delicados.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · temperatura média</strong><span>Roupa do dia a dia, algodão/poliéster, camisas, T-shirts.</span><small>Boa opção para cargas mistas se a etiqueta permitir secador.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · temperatura baixa</strong><span>Sintéticos leves, peças finas, alguma roupa desportiva.</span><small>Apenas se a etiqueta permitir secador.</small></div></div><p class='faq-source-note'>Valores de referência do fabricante para esta família de secadores profissionais IPSO de 30 lb; o ajuste exato pode variar ligeiramente com a programação.</p>"},"dryerBall":{"q":"A roupa ficou enrolada durante a secagem: o que fazer?","a":"<p>Pode <strong>abrir a porta durante o ciclo</strong>: o secador para. Desfaça a bola, distribua a roupa e feche novamente.</p><div class='faq-tip'><strong>Para reiniciar:</strong> prima novamente a temperatura escolhida — <strong>HIGH, PERM PRESS / MEDIUM ou LOW</strong>. O secador reinicia automaticamente.</div>"},"ironer":{"q":"Como usar a calandra?","a":"<p>Pague na central e aguarde cerca de <strong>3–4 minutos de aquecimento</strong>. Arranca automaticamente. Preço: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Apenas para roupa plana adequada ao calor.</strong> Sem botões, fechos, peças metálicas/plásticas ou sintéticos sensíveis ao calor.</p><div class='faq-tip'><strong>Antes:</strong> passe a mão pela peça. Se sentir algo duro, grosso ou um fecho, <strong>não coloque na calandra</strong>.</div>"},"pets":{"q":"Onde lavar têxteis de animais?","a":"<p>Use apenas as máquinas marcadas <strong>ANIMAUX / PETS</strong> para mantas, camas e outros têxteis de animais. Disponíveis em <strong>7 kg e 14 kg</strong>.</p>"},"pay":{"q":"Como pagar?","a":"<p>Na central, <strong>selecione a máquina ou secador</strong> e pague com moedas, notas, cartão contactless ou smartphone. O ecrã guia-o passo a passo.</p><div class='faq-tip'><strong>Após o pagamento:</strong> se precisar de fatura, veja logo o ecrã: o código de 4 caracteres aparece apenas cerca de 5 segundos.</div>"},"code":{"q":"Para que serve o código após o pagamento?","a":"<p>Um <strong>código de 4 caracteres</strong> aparece durante cerca de <strong>5 segundos</strong> após o pagamento. Anote-o se quiser uma fatura. Pode ser usado durante <strong>24 horas</strong>.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Obter a fatura no WiLine ↗</a>"},"availability":{"q":"Como ver se uma máquina está livre?","a":"<p>Abra o WiLine: verá quais as máquinas livres e em funcionamento.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Ver máquinas no WiLine ↗</a>"},"notify":{"q":"Posso receber aviso quando o ciclo terminar?","a":"<p><strong>Sim.</strong><br>1. Abra o WiLine.<br>2. Encontre a sua máquina.<br>3. Prima o <strong>pequeno sino à direita da máquina</strong>.<br>4. Receberá uma notificação no final.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Abrir WiLine e ativar o sino ↗</a>"},"loyalty":{"q":"Como funciona o cartão de fidelidade?","a":"<p>O primeiro cartão é gratuito: <strong>40 € pagos = 40 € de crédito</strong> + 1 dose de detergente. As recargas seguintes oferecem crédito extra conforme o valor.</p>"},"ownDetergent":{"q":"Posso usar o meu próprio detergente?","a":"<p><strong>Sim, a escolha é sua.</strong> Traga o seu detergente se prefere a marca ou perfume habitual. Ou compre no local: <strong>Eco, Peles sensíveis, Premium, amaciadores, desinfetante e tira-nódoas oxigenado.</strong></p>"},"products":{"q":"Que produtos estão disponíveis?","a":"<p><strong>Detergentes:</strong> Eco, Peles sensíveis e Premium.<br><strong>Amaciadores:</strong> perfumado ou peles sensíveis.<br><strong>Outros:</strong> desinfetante e tira-nódoas oxigenado.</p>"},"cowork":{"q":"Posso trabalhar durante o ciclo?","a":"<p>Sim. Há uma mesa grande, lugares sentados e tomadas. Ative o sino no WiLine e trabalhe até ao fim do ciclo.</p>"},"parcels":{"q":"Há Vinted Go e bpost?","a":"<p>Sim. Pode entregar ou recolher pacotes Vinted Go e bpost / bbox durante a visita.</p>"},"basketsWater":{"q":"Há cestos e água descalcificada?","a":"<p>Sim. Há cestos disponíveis e a lavandaria utiliza água descalcificada.</p>"},"pro":{"q":"Sou profissional, posso contactar-vos?","a":"<p>Sim. Para visitas regulares, grandes volumes ou necessidades específicas, escolha <strong>“Profissional / tarifas”</strong> no formulário.</p><a class='faq-link' href='#contact'>Contactar POP’n WASH ↓</a>"},"problem":{"q":"Tenho um problema com uma máquina. O que faço?","a":"<p>Ligue ou envie WhatsApp para <strong>+32 486 999 251</strong>, ou use o formulário.</p>"},"suggestion":{"q":"Tenho uma ideia de melhoria. Como envio?","a":"<p>Escolha <strong>“Sugestão / melhoria”</strong> no formulário ou use a caixa de ideias na lavandaria.</p><a class='faq-link' href='#contact'>Enviar uma ideia ↓</a>"},"hours":{"q":"Quais são os horários e a morada?","a":"<p><strong>7/7 · 07:00–22:00</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Abrir rota ↗</a>"},"parking":{"q":"Onde posso estacionar?","a":"<p>Tem 30 minutos gratuitos na rua após registar a matrícula, além de várias opções de estacionamento próximas.</p>"}};
faqTranslations.ro={"washer":{"q":"Cum pornesc o mașină de spălat?","a":"<p>1. Puneți rufele în mașină.<br>2. Adăugați detergentul în mașină.<br>3. Alegeți programul.<br>4. Plătiți la centrală.<br><strong>Mașina pornește automat după plată.</strong></p>"},"capacity":{"q":"Ce capacitate de mașină aleg?","a":"<p>7 kg pentru o spălare mică, 14 kg pentru un volum mai mare, 20 kg pentru volume foarte mari sau piese voluminoase.</p><div class='faq-tip'><strong>Regulă simplă:</strong> nu îndesați rufele. Trebuie să puteți introduce <strong>o mână între partea de sus a rufelor și partea de sus a tamburului</strong>. Dacă nu, alegeți o mașină mai mare.</div><p>Un tambur prea plin spală și stoarce mai slab și poate prelungi stoarcerea.</p>"},"dryer":{"q":"Cum pornesc un uscător?","a":"<p>1. Puneți rufele în uscător.<br>2. Plătiți la centrală numărul de cicluri dorit.<br>3. Pe uscător, apăsați <strong>temperatura potrivită pentru rufe</strong>.<br>Fiecare ciclu = <strong>5 minute pentru 0,50 €</strong>.</p><div class='faq-tip'><strong>Regulă simplă:</strong> rufele trebuie să cadă și să se rotească liber. Pentru un volum mare, împărțiți-l în <strong>două uscătoare</strong>.</div>"},"dryerTemp":{"q":"Ce temperatură aleg la uscător?","a":"<p><strong>Uscătoarele noastre sunt profesionale și încălzesc eficient:</strong> alegeți în funcție de material și verificați eticheta.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · temperatură mare</strong><span>Prosoape, cearșafuri din bumbac, blugi, bumbac gros.</span><small>Evitați pentru sintetice, elastan și materiale delicate.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · temperatură medie</strong><span>Rufe obișnuite, bumbac/poliester, cămăși, tricouri.</span><small>Bun pentru încărcături mixte dacă eticheta permite uscarea.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · temperatură joasă</strong><span>Sintetice ușoare, haine subțiri, unele articole sport.</span><small>Doar dacă eticheta permite uscarea.</small></div></div><p class='faq-source-note'>Valori de referință ale producătorului pentru această familie de uscătoare profesionale IPSO de 30 lb; setarea exactă poate varia ușor în funcție de programare.</p>"},"dryerBall":{"q":"Rufele s-au strâns într-o bilă în uscător: ce fac?","a":"<p>Puteți <strong>deschide ușa în timpul ciclului</strong>: uscătorul se oprește. Desfaceți și redistribuiți rufele, apoi închideți ușa.</p><div class='faq-tip'><strong>Pentru repornire:</strong> apăsați din nou temperatura dorită — <strong>HIGH, PERM PRESS / MEDIUM sau LOW</strong>. Uscătorul repornește automat.</div>"},"ironer":{"q":"Cum folosesc calandrul?","a":"<p>Plătiți la centrală, apoi așteptați aproximativ <strong>3–4 minute de încălzire</strong>. Pornește automat. Tarif: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Doar pentru rufe plate potrivite pentru căldură.</strong> Fără nasturi, fermoare, piese metalice/plastice sau sintetice sensibile la căldură.</p><div class='faq-tip'><strong>Înainte:</strong> treceți mâna peste articol. Dacă simțiți ceva tare, gros sau o închidere, <strong>nu îl introduceți în calandru</strong>.</div>"},"pets":{"q":"Unde spăl textilele animalelor?","a":"<p>Folosiți doar mașinile marcate <strong>ANIMAUX / PETS</strong> pentru pături, culcușuri și alte textile de animale. Disponibile în <strong>7 kg și 14 kg</strong>.</p>"},"pay":{"q":"Cum plătesc?","a":"<p>La centrală, <strong>selectați mașina de spălat sau uscătorul</strong>, apoi plătiți cu monede, bancnote, card contactless sau smartphone. Ecranul vă ghidează.</p><div class='faq-tip'><strong>După plată:</strong> dacă aveți nevoie de factură, priviți imediat ecranul: codul de 4 caractere apare doar aproximativ 5 secunde.</div>"},"code":{"q":"La ce folosește codul afișat după plată?","a":"<p>Un <strong>cod de 4 caractere</strong> apare aproximativ <strong>5 secunde</strong> după plată. Notați-l pentru factură. Poate fi folosit timp de <strong>24 de ore</strong>.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Obține factura în WiLine ↗</a>"},"availability":{"q":"Cum văd dacă o mașină este liberă?","a":"<p>Deschideți WiLine: vedeți imediat mașinile libere și cele în funcțiune.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Vezi mașinile în WiLine ↗</a>"},"notify":{"q":"Pot primi notificare când se termină ciclul?","a":"<p><strong>Da.</strong><br>1. Deschideți WiLine.<br>2. Găsiți mașina.<br>3. Apăsați <strong>clopoțelul mic din dreapta mașinii</strong>.<br>4. Veți primi o notificare la final.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Deschide WiLine și activează clopoțelul ↗</a>"},"loyalty":{"q":"Cum funcționează cardul de fidelitate?","a":"<p>Primul card este gratuit: <strong>40 € plătiți = 40 € credit</strong> + 1 doză de detergent. Reîncărcările următoare oferă credit suplimentar în funcție de sumă.</p>"},"ownDetergent":{"q":"Pot folosi propriul detergent?","a":"<p><strong>Da, dvs. alegeți.</strong> Aduceți detergentul preferat dacă doriți marca sau parfumul obișnuit. Sau cumpărați pe loc: <strong>Eco, Piele sensibilă, Premium, balsamuri, dezinfectant și soluție oxigenată pentru pete.</strong></p>"},"products":{"q":"Ce produse sunt disponibile?","a":"<p><strong>Detergenți:</strong> Eco, Piele sensibilă și Premium.<br><strong>Balsamuri:</strong> parfumat sau piele sensibilă.<br><strong>Altele:</strong> dezinfectant și soluție oxigenată pentru pete.</p>"},"cowork":{"q":"Pot lucra în timpul ciclului?","a":"<p>Da. Aveți masă mare, scaune și prize. Activați clopoțelul WiLine și lucrați până la final.</p>"},"parcels":{"q":"Există Vinted Go și bpost?","a":"<p>Da. Puteți preda sau ridica pachete Vinted Go și bpost / bbox în timpul vizitei.</p>"},"basketsWater":{"q":"Există coșuri de rufe și apă dedurizată?","a":"<p>Da. Sunt disponibile coșuri de rufe, iar spălătoria folosește apă dedurizată.</p>"},"pro":{"q":"Sunt profesionist. Vă pot contacta?","a":"<p>Da. Pentru vizite regulate, volume mari sau nevoi speciale, alegeți <strong>„Profesional / tarife”</strong> în formular.</p><a class='faq-link' href='#contact'>Contactează POP’n WASH ↓</a>"},"problem":{"q":"Am o problemă cu o mașină. Ce fac?","a":"<p>Sunați sau trimiteți WhatsApp la <strong>+32 486 999 251</strong>, sau folosiți formularul.</p>"},"suggestion":{"q":"Am o idee de îmbunătățire. Cum o trimit?","a":"<p>Alegeți <strong>„Sugestie / îmbunătățire”</strong> în formular sau folosiți cutia de sugestii din spălătorie.</p><a class='faq-link' href='#contact'>Trimite o idee ↓</a>"},"hours":{"q":"Care sunt programul și adresa?","a":"<p><strong>7/7 · 07:00–22:00</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Deschide traseul ↗</a>"},"parking":{"q":"Unde pot parca?","a":"<p>Aveți 30 de minute gratuite pe stradă după înregistrarea numărului de înmatriculare, plus mai multe opțiuni de parcare în apropiere.</p>"}};

faqTranslations.pl={"washer":{"q":"Jak uruchomić pralkę?","a":"<p>1. Włóż pranie do pralki.<br>2. Dodaj detergent do pralki.<br>3. Wybierz program.<br>4. Zapłać w terminalu.<br><strong>Pralka uruchamia się automatycznie po płatności.</strong></p>"},"capacity":{"q":"Jaką pojemność pralki wybrać?","a":"<p>7 kg na małe pranie, 14 kg na większą ilość, 20 kg na bardzo duże wsady lub duże rzeczy.</p><div class='faq-tip'><strong>Prosta zasada:</strong> nie upychaj prania. Powinna zmieścić się <strong>jedna dłoń między górą prania a górą bębna</strong>. Jeśli nie, wybierz większą pralkę.</div><p>Przeładowany bęben gorzej pierze i wiruje, a wirowanie może trwać dłużej.</p>"},"dryer":{"q":"Jak uruchomić suszarkę?","a":"<p>1. Włóż pranie do suszarki.<br>2. Zapłać w terminalu za wybraną liczbę cykli.<br>3. Na suszarce wybierz <strong>temperaturę odpowiednią do tkanin</strong>.<br>Każdy cykl = <strong>5 minut za 0,50 €</strong>.</p><div class='faq-tip'><strong>Prosta zasada:</strong> pranie powinno swobodnie opadać i obracać się. Duży wsad podziel między <strong>dwie suszarki</strong>.</div>"},"dryerTemp":{"q":"Jaką temperaturę wybrać w suszarce?","a":"<p><strong>Nasze suszarki są profesjonalne i grzeją skutecznie:</strong> dobierz temperaturę do tkaniny i sprawdź metkę.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · wysoka temperatura</strong><span>Ręczniki, bawełniana pościel, jeans, gruba bawełna.</span><small>Nie dla syntetyków, elastanu i delikatnych tkanin.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · średnia temperatura</strong><span>Codzienne pranie, bawełna/poliester, koszule, T-shirty.</span><small>Dobra dla mieszanego wsadu, jeśli metka pozwala na suszarkę.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · niska temperatura</strong><span>Lekkie syntetyki, cienkie ubrania, część odzieży sportowej.</span><small>Tylko jeśli metka pozwala na suszarkę.</small></div></div><p class='faq-source-note'>Temperatury są wartościami orientacyjnymi producenta dla tej rodziny profesjonalnych suszarek IPSO 30 lb; ustawienie może się nieznacznie różnić zależnie od programu.</p>"},"dryerBall":{"q":"Pranie zbiło się w kulę podczas suszenia — co zrobić?","a":"<p>Możesz <strong>otworzyć drzwi w trakcie cyklu</strong>: suszarka się zatrzyma. Rozdziel pranie, rozłóż je w bębnie i zamknij drzwi.</p><div class='faq-tip'><strong>Aby wznowić:</strong> ponownie wybierz temperaturę — <strong>HIGH, PERM PRESS / MEDIUM lub LOW</strong>. Suszarka ruszy automatycznie.</div>"},"ironer":{"q":"Jak używać magla?","a":"<p>Zapłać w terminalu i odczekaj około <strong>3–4 minut nagrzewania</strong>. Magiel uruchamia się automatycznie. Cena: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Tylko do płaskich tkanin odpornych na ciepło.</strong> Bez guzików, zamków, elementów metalowych/plastikowych ani syntetyków wrażliwych na ciepło.</p><div class='faq-tip'><strong>Przed użyciem:</strong> przejedź dłonią po tkaninie. Jeśli wyczujesz coś twardego, grubego lub zapięcie, <strong>nie wkładaj do magla</strong>.</div>"},"pets":{"q":"Gdzie prać tekstylia zwierzęce?","a":"<p>Używaj tylko maszyn oznaczonych <strong>ANIMAUX / PETS</strong> do koców, legowisk i innych tekstyliów zwierzęcych. Dostępne pojemności: <strong>7 kg i 14 kg</strong>.</p>"},"pay":{"q":"Jak zapłacić?","a":"<p>W terminalu <strong>wybierz pralkę lub suszarkę</strong>, potem zapłać monetami, banknotami, kartą zbliżeniową lub smartfonem. Ekran prowadzi krok po kroku.</p><div class='faq-tip'><strong>Po płatności:</strong> jeśli potrzebujesz faktury, od razu spójrz na ekran — 4-znakowy kod pojawia się tylko na około 5 sekund.</div>"},"code":{"q":"Do czego służy kod po płatności?","a":"<p><strong>4-znakowy kod</strong> pojawia się na około <strong>5 sekund</strong> po płatności. Zapisz go do faktury. Jest ważny przez <strong>24 godziny</strong>.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Pobierz fakturę w WiLine ↗</a>"},"availability":{"q":"Jak sprawdzić, czy maszyna jest wolna?","a":"<p>Otwórz WiLine: zobaczysz, które maszyny są wolne, a które pracują.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Zobacz maszyny w WiLine ↗</a>"},"notify":{"q":"Czy mogę dostać powiadomienie po zakończeniu cyklu?","a":"<p><strong>Tak.</strong><br>1. Otwórz WiLine.<br>2. Znajdź swoją maszynę.<br>3. Kliknij <strong>mały dzwonek po prawej stronie maszyny</strong>.<br>4. Otrzymasz powiadomienie po zakończeniu cyklu.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Otwórz WiLine i włącz dzwonek ↗</a>"},"loyalty":{"q":"Jak działa karta lojalnościowa?","a":"<p>Pierwsza karta jest bezpłatna: <strong>40 € wpłacone = 40 € kredytu</strong> + 1 saszetka detergentu. Kolejne doładowania dają dodatkowy kredyt zależnie od kwoty.</p>"},"ownDetergent":{"q":"Czy mogę użyć własnego detergentu?","a":"<p><strong>Tak, wybór należy do Ciebie.</strong> Weź własny detergent, jeśli wolisz swoją markę lub zapach. Albo kup na miejscu: <strong>Eco, Sensitive, Premium, płyny do płukania, środek dezynfekujący i tlenowy odplamiacz.</strong></p>"},"products":{"q":"Jakie produkty są dostępne?","a":"<p><strong>Detergenty:</strong> Eco, Sensitive i Premium.<br><strong>Płyny do płukania:</strong> zapachowy lub sensitive.<br><strong>Inne:</strong> środek dezynfekujący i tlenowy odplamiacz.</p>"},"cowork":{"q":"Czy mogę pracować podczas cyklu?","a":"<p>Tak. Dostępny jest duży stół, miejsca siedzące i gniazdka. Włącz dzwonek WiLine i pracuj do końca cyklu.</p>"},"parcels":{"q":"Czy są Vinted Go i bpost?","a":"<p>Tak. Podczas wizyty możesz nadać lub odebrać paczki Vinted Go i bpost / bbox.</p>"},"basketsWater":{"q":"Czy są kosze na pranie i zmiękczona woda?","a":"<p>Tak. Kosze są dostępne na miejscu, a pralnia korzysta ze zmiękczonej wody.</p>"},"pro":{"q":"Prowadzę firmę. Czy mogę się skontaktować?","a":"<p>Tak. Przy regularnych wizytach, dużych ilościach lub szczególnych potrzebach wybierz w formularzu <strong>„Firma / ceny”</strong>.</p><a class='faq-link' href='#contact'>Skontaktuj się z POP’n WASH ↓</a>"},"problem":{"q":"Mam problem z maszyną. Co zrobić?","a":"<p>Zadzwoń lub napisz na WhatsApp: <strong>+32 486 999 251</strong>, albo użyj formularza.</p>"},"suggestion":{"q":"Mam pomysł na ulepszenie. Jak go wysłać?","a":"<p>W formularzu wybierz <strong>„Sugestia / ulepszenie”</strong> albo skorzystaj ze skrzynki pomysłów w pralni.</p><a class='faq-link' href='#contact'>Wyślij pomysł ↓</a>"},"hours":{"q":"Jakie są godziny otwarcia i adres?","a":"<p><strong>7 dni · 07:00–22:00</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Otwórz trasę ↗</a>"},"parking":{"q":"Gdzie mogę zaparkować?","a":"<p>Masz 30 minut bezpłatnego parkowania na ulicy po rejestracji numeru rejestracyjnego oraz kilka parkingów w pobliżu.</p>"}};
faqTranslations.uk={"washer":{"q":"Як запустити пральну машину?","a":"<p>1. Покладіть речі в машину.<br>2. Додайте пральний засіб у машину.<br>3. Оберіть програму.<br>4. Оплатіть у терміналі.<br><strong>Пральна машина запускається автоматично після оплати.</strong></p>"},"capacity":{"q":"Який розмір машини обрати?","a":"<p>7 кг для невеликого прання, 14 кг для більшого обсягу, 20 кг для дуже великих обсягів або великих речей.</p><div class='faq-tip'><strong>Просте правило:</strong> не набивайте барабан. Між верхом речей і верхом барабана має проходити <strong>одна долоня</strong>. Якщо ні — оберіть більшу машину.</div><p>Перевантажений барабан гірше пере й віджимає, а віджим може тривати довше.</p>"},"dryer":{"q":"Як запустити сушарку?","a":"<p>1. Покладіть речі в сушарку.<br>2. Оплатіть потрібну кількість циклів у терміналі.<br>3. На сушарці оберіть <strong>температуру, що підходить тканині</strong>.<br>Кожен цикл = <strong>5 хвилин за 0,50 €</strong>.</p><div class='faq-tip'><strong>Просте правило:</strong> речі мають вільно падати й обертатися. Великий обсяг краще розділити між <strong>двома сушарками</strong>.</div>"},"dryerTemp":{"q":"Яку температуру обрати на сушарці?","a":"<p><strong>Наші сушарки професійні й нагрівають ефективно:</strong> завжди орієнтуйтеся на тканину та етикетку.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · висока температура</strong><span>Рушники, бавовняні простирадла, джинси, щільна бавовна.</span><small>Не для синтетики, еластану та делікатних тканин.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · середня температура</strong><span>Щоденні речі, бавовна/поліестер, сорочки, футболки.</span><small>Добре для змішаних речей, якщо етикетка дозволяє сушарку.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · низька температура</strong><span>Легка синтетика, тонкі речі, частина спортивного одягу.</span><small>Лише якщо етикетка дозволяє сушарку.</small></div></div><p class='faq-source-note'>Це орієнтовні значення виробника для цієї серії професійних сушарок IPSO 30 lb; фактичне налаштування може трохи відрізнятися залежно від програмування.</p>"},"dryerBall":{"q":"Речі збилися в клубок під час сушіння — що робити?","a":"<p>Можна <strong>відкрити дверцята під час циклу</strong>: сушарка зупиниться. Розправте речі, розподіліть їх у барабані й закрийте дверцята.</p><div class='faq-tip'><strong>Щоб продовжити:</strong> знову натисніть потрібну температуру — <strong>HIGH, PERM PRESS / MEDIUM або LOW</strong>. Сушарка запуститься автоматично.</div>"},"ironer":{"q":"Як користуватися каландром?","a":"<p>Оплатіть у терміналі й зачекайте близько <strong>3–4 хвилин нагрівання</strong>. Каландр запускається автоматично. Ціна: <strong>2,00 € / 6 хв</strong>.</p><p class='faq-warning'><strong>Лише для плоскої білизни, придатної до нагрівання.</strong> Без ґудзиків, блискавок, металевих/пластикових деталей та чутливої до тепла синтетики.</p><div class='faq-tip'><strong>Перед використанням:</strong> проведіть рукою по тканині. Якщо є твердий, товстий елемент або застібка, <strong>не кладіть у каландр</strong>.</div>"},"pets":{"q":"Де прати текстиль для тварин?","a":"<p>Використовуйте лише машини з позначкою <strong>ANIMAUX / PETS</strong> для ковдр, лежанок та інших речей тварин. Є машини на <strong>7 кг і 14 кг</strong>.</p>"},"pay":{"q":"Як оплатити?","a":"<p>У терміналі <strong>оберіть пральну машину або сушарку</strong>, потім оплатіть монетами, банкнотами, безконтактною карткою або смартфоном. Екран підкаже кроки.</p><div class='faq-tip'><strong>Після оплати:</strong> якщо потрібен рахунок, одразу подивіться на екран — 4-символьний код показується приблизно 5 секунд.</div>"},"code":{"q":"Для чого код після оплати?","a":"<p><strong>4-символьний код</strong> показується приблизно <strong>5 секунд</strong> після оплати. Запишіть його для рахунку. Він діє <strong>24 години</strong>.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Отримати рахунок у WiLine ↗</a>"},"availability":{"q":"Як перевірити, чи машина вільна?","a":"<p>Відкрийте WiLine: там видно вільні машини та ті, що працюють.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Переглянути машини в WiLine ↗</a>"},"notify":{"q":"Чи можу я отримати сповіщення про завершення?","a":"<p><strong>Так.</strong><br>1. Відкрийте WiLine.<br>2. Знайдіть свою машину.<br>3. Натисніть <strong>маленький дзвіночок праворуч від машини</strong>.<br>4. Після завершення циклу отримаєте сповіщення.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Відкрити WiLine та ввімкнути дзвіночок ↗</a>"},"loyalty":{"q":"Як працює картка лояльності?","a":"<p>Перша картка безкоштовна: <strong>40 € сплачено = 40 € кредиту</strong> + 1 пакетик засобу. Наступні поповнення дають додатковий кредит залежно від суми.</p>"},"ownDetergent":{"q":"Чи можна використовувати свій пральний засіб?","a":"<p><strong>Так, вибір за вами.</strong> Візьміть свій засіб, якщо віддаєте перевагу звичному бренду чи аромату. Або купіть на місці: <strong>Eco, Sensitive, Premium, кондиціонери, дезінфектор і кисневий засіб від плям.</strong></p>"},"products":{"q":"Які засоби доступні?","a":"<p><strong>Пральні засоби:</strong> Eco, Sensitive і Premium.<br><strong>Кондиціонери:</strong> ароматизований або Sensitive.<br><strong>Інше:</strong> дезінфектор і кисневий засіб від плям.</p>"},"cowork":{"q":"Чи можна працювати під час циклу?","a":"<p>Так. Є великий стіл, місця для сидіння та розетки. Увімкніть дзвіночок WiLine і спокійно працюйте до завершення.</p>"},"parcels":{"q":"Чи є Vinted Go і bpost?","a":"<p>Так. Під час візиту можна здати або забрати посилки Vinted Go та bpost / bbox.</p>"},"basketsWater":{"q":"Чи є кошики для білизни та пом’якшена вода?","a":"<p>Так. Кошики доступні на місці, а пральня використовує пом’якшену воду.</p>"},"pro":{"q":"Я представляю бізнес. Чи можу звернутися?","a":"<p>Так. Для регулярних візитів, великих обсягів або особливих потреб у формі оберіть <strong>«Бізнес / тарифи»</strong>.</p><a class='faq-link' href='#contact'>Зв’язатися з POP’n WASH ↓</a>"},"problem":{"q":"Проблема з машиною — що робити?","a":"<p>Зателефонуйте або напишіть у WhatsApp на <strong>+32 486 999 251</strong>, або скористайтеся формою.</p>"},"suggestion":{"q":"Є ідея покращення. Як її надіслати?","a":"<p>У формі оберіть <strong>«Пропозиція / покращення»</strong> або скористайтеся скринькою ідей у пральні.</p><a class='faq-link' href='#contact'>Надіслати ідею ↓</a>"},"hours":{"q":"Які години роботи та адреса?","a":"<p><strong>7/7 · 07:00–22:00</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Відкрити маршрут ↗</a>"},"parking":{"q":"Де можна припаркуватися?","a":"<p>30 хвилин безкоштовного паркування на вулиці після реєстрації номера авто, а також кілька паркінгів поруч.</p>"}};
faqTranslations.ru={"washer":{"q":"Как запустить стиральную машину?","a":"<p>1. Загрузите бельё в машину.<br>2. Добавьте средство в стиральную машину.<br>3. Выберите программу.<br>4. Оплатите на терминале.<br><strong>Машина запускается автоматически после оплаты.</strong></p>"},"capacity":{"q":"Какой размер машины выбрать?","a":"<p>7 кг для небольшой стирки, 14 кг для большего объёма, 20 кг для очень больших объёмов или крупных вещей.</p><div class='faq-tip'><strong>Простое правило:</strong> не утрамбовывайте бельё. Между бельём и верхом барабана должна проходить <strong>одна ладонь</strong>. Если нет — выберите машину больше.</div><p>Перегруженный барабан хуже стирает и отжимает, а отжим может занять больше времени.</p>"},"dryer":{"q":"Как запустить сушилку?","a":"<p>1. Загрузите бельё в сушилку.<br>2. Оплатите нужное число циклов на терминале.<br>3. На сушилке выберите <strong>температуру, подходящую ткани</strong>.<br>Каждый цикл = <strong>5 минут за 0,50 €</strong>.</p><div class='faq-tip'><strong>Простое правило:</strong> бельё должно свободно падать и вращаться. Большой объём лучше разделить между <strong>двумя сушилками</strong>.</div>"},"dryerTemp":{"q":"Какую температуру выбрать на сушилке?","a":"<p><strong>Наши сушилки профессиональные и эффективно нагревают:</strong> выбирайте температуру по ткани и всегда проверяйте ярлык.</p><div class='dryer-temp-grid'><div class='dryer-temp high'><b>HIGH</b><strong>≈ 80 °C · высокая температура</strong><span>Полотенца, хлопковые простыни, джинсы, плотный хлопок.</span><small>Не для синтетики, эластана и деликатных тканей.</small></div><div class='dryer-temp medium'><b>PERM PRESS / MEDIUM</b><strong>≈ 69 °C · средняя температура</strong><span>Повседневное бельё, хлопок/полиэстер, рубашки, футболки.</span><small>Для смешанной загрузки, если ярлык разрешает сушку.</small></div><div class='dryer-temp low'><b>LOW</b><strong>≈ 58 °C · низкая температура</strong><span>Лёгкая синтетика, тонкая одежда, некоторые спортивные вещи.</span><small>Только если ярлык разрешает сушку.</small></div></div><p class='faq-source-note'>Это ориентировочные значения производителя для этой серии профессиональных сушилок IPSO 30 lb; точная настройка может немного отличаться в зависимости от программирования.</p>"},"dryerBall":{"q":"Бельё сбилось в комок во время сушки — что делать?","a":"<p>Можно <strong>открыть дверцу во время цикла</strong>: сушилка остановится. Расправьте бельё, распределите его в барабане и закройте дверцу.</p><div class='faq-tip'><strong>Чтобы продолжить:</strong> снова нажмите нужную температуру — <strong>HIGH, PERM PRESS / MEDIUM или LOW</strong>. Сушилка запустится автоматически.</div>"},"ironer":{"q":"Как пользоваться каландром?","a":"<p>Оплатите на терминале и подождите около <strong>3–4 минут нагрева</strong>. Каландр запускается автоматически. Цена: <strong>2,00 € / 6 мин</strong>.</p><p class='faq-warning'><strong>Только для плоского белья, подходящего для нагрева.</strong> Без пуговиц, молний, металлических/пластиковых деталей и чувствительной к теплу синтетики.</p><div class='faq-tip'><strong>Перед использованием:</strong> проведите рукой по ткани. Если есть твёрдая, толстая деталь или застёжка, <strong>не кладите вещь в каландр</strong>.</div>"},"pets":{"q":"Где стирать текстиль для животных?","a":"<p>Используйте только машины с маркировкой <strong>ANIMAUX / PETS</strong> для покрывал, лежанок и других вещей животных. Доступны <strong>7 кг и 14 кг</strong>.</p>"},"pay":{"q":"Как оплатить?","a":"<p>На терминале <strong>выберите стиральную машину или сушилку</strong>, затем оплатите монетами, банкнотами, бесконтактной картой или смартфоном. Экран подскажет шаги.</p><div class='faq-tip'><strong>После оплаты:</strong> если нужен счёт, сразу посмотрите на экран — 4-символьный код показывается около 5 секунд.</div>"},"code":{"q":"Для чего код после оплаты?","a":"<p><strong>4-символьный код</strong> появляется примерно на <strong>5 секунд</strong> после оплаты. Запишите его для счёта. Он действует <strong>24 часа</strong>.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Получить счёт в WiLine ↗</a>"},"availability":{"q":"Как проверить, свободна ли машина?","a":"<p>Откройте WiLine: там видно свободные и работающие машины.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Посмотреть машины в WiLine ↗</a>"},"notify":{"q":"Можно получить уведомление об окончании цикла?","a":"<p><strong>Да.</strong><br>1. Откройте WiLine.<br>2. Найдите свою машину.<br>3. Нажмите <strong>маленький колокольчик справа от машины</strong>.<br>4. После завершения цикла придёт уведомление.</p><a class='faq-link' href='https://status.wi-line.fr/82973c2800815407e4de7ffc45cd77b8' target='_blank' rel='noopener'>Открыть WiLine и включить колокольчик ↗</a>"},"loyalty":{"q":"Как работает карта лояльности?","a":"<p>Первая карта бесплатна: <strong>40 € оплачено = 40 € кредита</strong> + 1 пакетик средства. Следующие пополнения дают дополнительный кредит в зависимости от суммы.</p>"},"ownDetergent":{"q":"Можно использовать своё средство?","a":"<p><strong>Да, выбор за вами.</strong> Возьмите своё средство, если предпочитаете привычную марку или запах. Или купите на месте: <strong>Eco, Sensitive, Premium, кондиционеры, дезинфицирующее средство и кислородный пятновыводитель.</strong></p>"},"products":{"q":"Какие средства доступны?","a":"<p><strong>Средства для стирки:</strong> Eco, Sensitive и Premium.<br><strong>Кондиционеры:</strong> ароматизированный или Sensitive.<br><strong>Другое:</strong> дезинфицирующее средство и кислородный пятновыводитель.</p>"},"cowork":{"q":"Можно работать во время цикла?","a":"<p>Да. Есть большой стол, места и розетки. Включите колокольчик WiLine и спокойно работайте до завершения.</p>"},"parcels":{"q":"Есть Vinted Go и bpost?","a":"<p>Да. Во время визита можно отправить или получить посылки Vinted Go и bpost / bbox.</p>"},"basketsWater":{"q":"Есть корзины для белья и смягчённая вода?","a":"<p>Да. Корзины доступны на месте, а прачечная использует смягчённую воду.</p>"},"pro":{"q":"Я представляю бизнес. Можно связаться?","a":"<p>Да. Для регулярных визитов, больших объёмов или особых потребностей в форме выберите <strong>«Бизнес / тарифы»</strong>.</p><a class='faq-link' href='#contact'>Связаться с POP’n WASH ↓</a>"},"problem":{"q":"Проблема с машиной — что делать?","a":"<p>Позвоните или напишите в WhatsApp на <strong>+32 486 999 251</strong>, либо используйте форму.</p>"},"suggestion":{"q":"Есть идея улучшения. Как её отправить?","a":"<p>В форме выберите <strong>«Предложение / улучшение»</strong> или используйте ящик идей в прачечной.</p><a class='faq-link' href='#contact'>Отправить идею ↓</a>"},"hours":{"q":"Какой график и адрес?","a":"<p><strong>7/7 · 07:00–22:00</strong><br>Rue de Namur, 72 · 1300 Wavre</p><a class='faq-link' href='https://www.google.com/maps/search/?api=1&query=POP%27n%20WASH%20Wavre&query_place_id=ChIJ616yFqB9wUcRf55Cp9uBEM0' target='_blank' rel='noopener'>Открыть маршрут ↗</a>"},"parking":{"q":"Где можно припарковаться?","a":"<p>30 минут бесплатной парковки на улице после регистрации номера автомобиля, плюс несколько вариантов парковки рядом.</p>"}};


// Keep detailed FAQ aligned with the first-visit guide
Object.assign(faqTranslations.en,{"washer":{"q":"How do I start a washer?","a":"<p>1. Choose a washer and check its number.<br>2. Load the laundry, add detergent and choose the programme.<br>3. At the terminal, select <strong>the same number</strong> and pay.<br><strong>The washer starts automatically after payment.</strong></p>"},"dryer":{"q":"How do I start a dryer?","a":"<p>1. Choose a dryer and check its number.<br>2. Load the laundry.<br>3. At the terminal, select <strong>the same number</strong>, choose the time and pay.<br>4. On the dryer, press <strong>HIGH, MEDIUM or LOW</strong>.<br>Each cycle = <strong>5 minutes for €0.50</strong>.</p><div class='faq-tip'><strong>Easy rule:</strong> laundry must tumble freely. For a large load, split it between <strong>two dryers</strong> for faster, more even drying.</div>"},"ironer":{"q":"How do I use the flatwork ironer?","a":"<p>At the terminal, choose <strong>Other → Ironer</strong>, select the time and pay. Wait about <strong>3–4 minutes for heating</strong>. It starts automatically. Price: <strong>€2.00 / 6 min</strong>.</p><p class='faq-warning'><strong>Only for flat linen suitable for heat.</strong> No buttons, zips, metal/plastic parts or heat-sensitive synthetics.</p><div class='faq-tip'><strong>Before feeding it in:</strong> run your hand over the item. If you feel anything hard, thick or a fastening, <strong>do not put it through the ironer</strong>.</div>"}});
Object.assign(faqTranslations.nl,{"washer":{"q":"Hoe start ik een wasmachine?","a":"<p>1. Kies een wasmachine en kijk naar het nummer.<br>2. Laad de was, voeg wasmiddel toe en kies het programma.<br>3. Kies aan de centrale <strong>hetzelfde nummer</strong> en betaal.<br><strong>De wasmachine start automatisch na betaling.</strong></p>"},"dryer":{"q":"Hoe start ik een droger?","a":"<p>1. Kies een droger en kijk naar het nummer.<br>2. Laad de was.<br>3. Kies aan de centrale <strong>hetzelfde nummer</strong>, de tijd en betaal.<br>4. Druk op de droger op <strong>HIGH, MEDIUM of LOW</strong>.<br>Elke cyclus = <strong>5 minuten voor €0,50</strong>.</p><div class='faq-tip'><strong>Eenvoudige regel:</strong> de was moet vrij kunnen draaien. Verdeel een grote lading over <strong>twee drogers</strong>.</div>"},"ironer":{"q":"Hoe gebruik ik de mangel?","a":"<p>Kies aan de centrale <strong>Andere → Mangel</strong>, kies de tijd en betaal. Wacht ongeveer <strong>3–4 minuten opwarming</strong>. De mangel start automatisch. Tarief: <strong>€2,00 / 6 min</strong>.</p><p class='faq-warning'><strong>Alleen vlak wasgoed dat hitte verdraagt.</strong> Geen knopen, ritsen, metalen/plastic delen of hittegevoelige synthetische stoffen.</p><div class='faq-tip'><strong>Controle:</strong> ga met uw hand over het textiel. Voelt u iets hard, dik of een sluiting, <strong>stop het dan niet in de mangel</strong>.</div>"}});
Object.assign(faqTranslations.de,{"washer":{"q":"Wie starte ich eine Waschmaschine?","a":"<p>1. Waschmaschine wählen und Nummer ansehen.<br>2. Wäsche einlegen, Waschmittel dazugeben und Programm wählen.<br>3. An der Zahlstation <strong>dieselbe Nummer</strong> wählen und zahlen.<br><strong>Die Waschmaschine startet nach der Zahlung automatisch.</strong></p>"},"dryer":{"q":"Wie starte ich einen Trockner?","a":"<p>1. Trockner wählen und Nummer ansehen.<br>2. Wäsche einlegen.<br>3. An der Zahlstation <strong>dieselbe Nummer</strong>, Zeit wählen und zahlen.<br>4. Am Trockner <strong>HIGH, MEDIUM oder LOW</strong> drücken.<br>Jeder Zyklus = <strong>5 Minuten für 0,50 €</strong>.</p><div class='faq-tip'><strong>Einfache Regel:</strong> die Wäsche muss frei drehen können. Große Mengen auf <strong>zwei Trockner</strong> verteilen.</div>"},"ironer":{"q":"Wie benutze ich die Mangel?","a":"<p>An der Zahlstation <strong>Andere → Mangel</strong> wählen, Zeit wählen und zahlen. Etwa <strong>3–4 Minuten Aufheizzeit</strong> warten. Sie startet automatisch. Preis: <strong>2,00 € / 6 Min.</strong></p><p class='faq-warning'><strong>Nur für hitzegeeignete Flachwäsche.</strong> Keine Knöpfe, Reißverschlüsse, Metall-/Kunststoffteile oder hitzeempfindliche Synthetik.</p><div class='faq-tip'><strong>Vorher prüfen:</strong> bei harten, dicken Teilen oder Verschlüssen <strong>nicht mangeln</strong>.</div>"}});
Object.assign(faqTranslations.it,{"washer":{"q":"Come avvio una lavatrice?","a":"<p>1. Scegli la lavatrice e guarda il numero.<br>2. Carica il bucato, aggiungi il detersivo e scegli il programma.<br>3. Alla centrale seleziona <strong>lo stesso numero</strong> e paga.<br><strong>La lavatrice parte automaticamente dopo il pagamento.</strong></p>"},"dryer":{"q":"Come avvio un’asciugatrice?","a":"<p>1. Scegli l’asciugatrice e guarda il numero.<br>2. Carica il bucato.<br>3. Alla centrale seleziona <strong>lo stesso numero</strong>, scegli il tempo e paga.<br>4. Sull’asciugatrice premi <strong>HIGH, MEDIUM o LOW</strong>.<br>Ogni ciclo = <strong>5 minuti per 0,50 €</strong>.</p><div class='faq-tip'><strong>Regola semplice:</strong> il bucato deve girare liberamente. Per grandi volumi usa <strong>due asciugatrici</strong>.</div>"},"ironer":{"q":"Come usare la calandra?","a":"<p>Alla centrale scegli <strong>Altro → Calandra</strong>, scegli il tempo e paga. Attendi circa <strong>3–4 minuti di riscaldamento</strong>. Parte automaticamente. Tariffa: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Solo biancheria piana adatta al calore.</strong> Niente bottoni, zip, parti metalliche/plastiche o sintetici sensibili al calore.</p><div class='faq-tip'><strong>Prima:</strong> se senti qualcosa di duro, spesso o una chiusura, <strong>non inserirlo nella calandra</strong>.</div>"}});
Object.assign(faqTranslations.es,{"washer":{"q":"¿Cómo pongo en marcha una lavadora?","a":"<p>1. Elige la lavadora y mira su número.<br>2. Carga la ropa, añade detergente y elige el programa.<br>3. En la central selecciona <strong>el mismo número</strong> y paga.<br><strong>La lavadora arranca automáticamente después del pago.</strong></p>"},"dryer":{"q":"¿Cómo pongo en marcha una secadora?","a":"<p>1. Elige la secadora y mira su número.<br>2. Carga la ropa.<br>3. En la central selecciona <strong>el mismo número</strong>, elige el tiempo y paga.<br>4. En la secadora pulsa <strong>HIGH, MEDIUM o LOW</strong>.<br>Cada ciclo = <strong>5 minutos por 0,50 €</strong>.</p><div class='faq-tip'><strong>Regla fácil:</strong> la ropa debe girar libremente. Para una carga grande usa <strong>dos secadoras</strong>.</div>"},"ironer":{"q":"¿Cómo uso la calandra?","a":"<p>En la central elige <strong>Otro → Calandra</strong>, elige el tiempo y paga. Espera unos <strong>3–4 minutos de calentamiento</strong>. Arranca automáticamente. Precio: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Solo para ropa plana apta para calor.</strong> No botones, cremalleras, piezas metálicas/plásticas ni sintéticos sensibles al calor.</p><div class='faq-tip'><strong>Antes:</strong> si notas algo duro, grueso o un cierre, <strong>no lo introduzcas en la calandra</strong>.</div>"}});
Object.assign(faqTranslations.pt,{"washer":{"q":"Como iniciar uma máquina de lavar?","a":"<p>1. Escolha a máquina e veja o número.<br>2. Carregue a roupa, adicione detergente e escolha o programa.<br>3. Na central selecione <strong>o mesmo número</strong> e pague.<br><strong>A máquina inicia automaticamente após o pagamento.</strong></p>"},"dryer":{"q":"Como iniciar um secador?","a":"<p>1. Escolha o secador e veja o número.<br>2. Carregue a roupa.<br>3. Na central selecione <strong>o mesmo número</strong>, escolha o tempo e pague.<br>4. No secador prima <strong>HIGH, MEDIUM ou LOW</strong>.<br>Cada ciclo = <strong>5 minutos por 0,50 €</strong>.</p><div class='faq-tip'><strong>Regra simples:</strong> a roupa deve rodar livremente. Para uma carga grande use <strong>dois secadores</strong>.</div>"},"ironer":{"q":"Como usar a calandra?","a":"<p>Na central escolha <strong>Outro → Calandra</strong>, escolha o tempo e pague. Aguarde cerca de <strong>3–4 minutos de aquecimento</strong>. Arranca automaticamente. Preço: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Apenas roupa plana adequada ao calor.</strong> Sem botões, fechos, peças metálicas/plásticas ou sintéticos sensíveis ao calor.</p><div class='faq-tip'><strong>Antes:</strong> se sentir algo duro, grosso ou um fecho, <strong>não coloque na calandra</strong>.</div>"}});
Object.assign(faqTranslations.ro,{"washer":{"q":"Cum pornesc o mașină de spălat?","a":"<p>1. Alegeți mașina și verificați numărul.<br>2. Încărcați rufele, adăugați detergent și alegeți programul.<br>3. La centrală selectați <strong>același număr</strong> și plătiți.<br><strong>Mașina pornește automat după plată.</strong></p>"},"dryer":{"q":"Cum pornesc un uscător?","a":"<p>1. Alegeți uscătorul și verificați numărul.<br>2. Încărcați rufele.<br>3. La centrală selectați <strong>același număr</strong>, timpul și plătiți.<br>4. Pe uscător apăsați <strong>HIGH, MEDIUM sau LOW</strong>.<br>Fiecare ciclu = <strong>5 minute pentru 0,50 €</strong>.</p><div class='faq-tip'><strong>Regulă simplă:</strong> rufele trebuie să se rotească liber. Pentru volum mare folosiți <strong>două uscătoare</strong>.</div>"},"ironer":{"q":"Cum folosesc calandrul?","a":"<p>La centrală alegeți <strong>Altele → Calandru</strong>, alegeți timpul și plătiți. Așteptați aproximativ <strong>3–4 minute de încălzire</strong>. Pornește automat. Tarif: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Doar pentru rufe plate potrivite pentru căldură.</strong> Fără nasturi, fermoare, piese metalice/plastice sau sintetice sensibile la căldură.</p><div class='faq-tip'><strong>Înainte:</strong> dacă simțiți ceva tare, gros sau o închidere, <strong>nu îl introduceți în calandru</strong>.</div>"}});
Object.assign(faqTranslations.pl,{"washer":{"q":"Jak uruchomić pralkę?","a":"<p>1. Wybierz pralkę i sprawdź jej numer.<br>2. Załaduj pranie, dodaj detergent i wybierz program.<br>3. W terminalu wybierz <strong>ten sam numer</strong> i zapłać.<br><strong>Pralka uruchamia się automatycznie po płatności.</strong></p>"},"dryer":{"q":"Jak uruchomić suszarkę?","a":"<p>1. Wybierz suszarkę i sprawdź jej numer.<br>2. Załaduj pranie.<br>3. W terminalu wybierz <strong>ten sam numer</strong>, czas i zapłać.<br>4. Na suszarce naciśnij <strong>HIGH, MEDIUM lub LOW</strong>.<br>Każdy cykl = <strong>5 minut za 0,50 €</strong>.</p><div class='faq-tip'><strong>Prosta zasada:</strong> pranie powinno swobodnie się obracać. Duży wsad podziel między <strong>dwie suszarki</strong>.</div>"},"ironer":{"q":"Jak używać magla?","a":"<p>W terminalu wybierz <strong>Inne → Magiel</strong>, wybierz czas i zapłać. Poczekaj około <strong>3–4 minut na nagrzanie</strong>. Magiel uruchamia się automatycznie. Cena: <strong>2,00 € / 6 min</strong>.</p><p class='faq-warning'><strong>Tylko do płaskich tkanin odpornych na ciepło.</strong> Bez guzików, zamków, elementów metalowych/plastikowych ani syntetyków wrażliwych na ciepło.</p><div class='faq-tip'><strong>Przed:</strong> jeśli wyczujesz coś twardego, grubego lub zapięcie, <strong>nie wkładaj do magla</strong>.</div>"}});
Object.assign(faqTranslations.uk,{"washer":{"q":"Як запустити пральну машину?","a":"<p>1. Оберіть пральну машину й подивіться її номер.<br>2. Завантажте речі, додайте засіб і оберіть програму.<br>3. У терміналі виберіть <strong>той самий номер</strong> і оплатіть.<br><strong>Пральна машина запускається автоматично після оплати.</strong></p>"},"dryer":{"q":"Як запустити сушарку?","a":"<p>1. Оберіть сушарку й подивіться її номер.<br>2. Завантажте речі.<br>3. У терміналі виберіть <strong>той самий номер</strong>, час і оплатіть.<br>4. На сушарці натисніть <strong>HIGH, MEDIUM або LOW</strong>.<br>Кожен цикл = <strong>5 хвилин за 0,50 €</strong>.</p><div class='faq-tip'><strong>Просте правило:</strong> речі мають вільно обертатися. Великий обсяг краще розділити між <strong>двома сушарками</strong>.</div>"},"ironer":{"q":"Як користуватися каландром?","a":"<p>У терміналі виберіть <strong>Інше → Каландр</strong>, оберіть час і оплатіть. Зачекайте близько <strong>3–4 хвилин нагрівання</strong>. Каландр запускається автоматично. Ціна: <strong>2,00 € / 6 хв</strong>.</p><p class='faq-warning'><strong>Лише для плоскої білизни, придатної до нагрівання.</strong> Без ґудзиків, блискавок, металевих/пластикових деталей та чутливої до тепла синтетики.</p><div class='faq-tip'><strong>Перед:</strong> якщо є твердий, товстий елемент або застібка, <strong>не кладіть у каландр</strong>.</div>"}});
Object.assign(faqTranslations.ru,{"washer":{"q":"Как запустить стиральную машину?","a":"<p>1. Выберите стиральную машину и посмотрите её номер.<br>2. Загрузите бельё, добавьте средство и выберите программу.<br>3. На терминале выберите <strong>тот же номер</strong> и оплатите.<br><strong>Машина запускается автоматически после оплаты.</strong></p>"},"dryer":{"q":"Как запустить сушилку?","a":"<p>1. Выберите сушилку и посмотрите её номер.<br>2. Загрузите бельё.<br>3. На терминале выберите <strong>тот же номер</strong>, время и оплатите.<br>4. На сушилке нажмите <strong>HIGH, MEDIUM или LOW</strong>.<br>Каждый цикл = <strong>5 минут за 0,50 €</strong>.</p><div class='faq-tip'><strong>Простое правило:</strong> бельё должно свободно вращаться. Большой объём лучше разделить между <strong>двумя сушилками</strong>.</div>"},"ironer":{"q":"Как пользоваться каландром?","a":"<p>На терминале выберите <strong>Другое → Каландр</strong>, выберите время и оплатите. Подождите около <strong>3–4 минут нагрева</strong>. Каландр запускается автоматически. Цена: <strong>2,00 € / 6 мин</strong>.</p><p class='faq-warning'><strong>Только для плоского белья, подходящего для нагрева.</strong> Без пуговиц, молний, металлических/пластиковых деталей и чувствительной к теплу синтетики.</p><div class='faq-tip'><strong>Перед:</strong> если есть твёрдая, толстая деталь или застёжка, <strong>не кладите вещь в каландр</strong>.</div>"}});

