// Contact form: direct email delivery via FormSubmit AJAX.
const contactForm=document.getElementById('contactForm');
if(contactForm){
  const status=document.getElementById('formStatus');
  const firstName=document.getElementById('contactFirstName');
  const subject=document.getElementById('contactSubject');
  const proButton=document.getElementById('proContactButton');
  if(proButton) proButton.addEventListener('click',()=>{
    setTimeout(()=>{
      if(subject) subject.value='Professionnel / tarifs';
      if(firstName) firstName.focus({preventScroll:true});
    },350);
  });
  contactForm.addEventListener('submit',async e=>{
    e.preventDefault();
    if(!contactForm.reportValidity()) return;
    const button=contactForm.querySelector('button[type="submit"]');
    const buttonText=button.querySelector('span');
    const original=buttonText.textContent;
    const fm=formMessages[currentLang]||formMessages.fr;
    button.disabled=true; buttonText.textContent=fm.sending;
    status.className='form-status'; status.textContent='';
    const data=new FormData(contactForm);
    data.append('_subject',"Nouveau message depuis le site POP'n WASH Wavre");
    data.append('_template','table');
    data.append('_captcha','false');
    try{
      const res=await fetch('https://formsubmit.co/ajax/ahb.lavoir@gmail.com',{method:'POST',headers:{'Accept':'application/json'},body:data});
      const body=await res.json().catch(()=>({}));
      if(!res.ok || body.success===false) throw new Error('send failed');
      const name=(firstName && firstName.value ? firstName.value : '').trim();
      status.className='form-status success';
      status.textContent=fm.success.replace('{name}',name?' '+name:'');
      contactForm.reset();
    }catch(err){
      status.className='form-status error';
      status.innerHTML=fm.error+' <a href="mailto:ahb.lavoir@gmail.com">ahb.lavoir@gmail.com</a>.';
    }finally{
      button.disabled=false; buttonText.textContent=original;
    }
  });
}


// 2026-10-07 compact FAQ categories on mobile/tablet
{
  const faqGroupMedia=window.matchMedia('(max-width: 1024px)');
  const faqGroups=[...document.querySelectorAll('.faq-group')];
  const setFaqGroupState=(group,open)=>{
    group.classList.toggle('is-open',open);
    const toggle=group.querySelector('.faq-group-toggle');
    if(toggle) toggle.setAttribute('aria-expanded',open?'true':'false');
    if(!open) group.querySelectorAll(':scope > .faq-item[open]').forEach(item=>item.removeAttribute('open'));
  };
  const syncFaqGroupMode=()=>{
    if(faqGroupMedia.matches){
      faqGroups.forEach(group=>setFaqGroupState(group,false));
    }else{
      faqGroups.forEach(group=>{
        group.classList.remove('is-open');
        const toggle=group.querySelector('.faq-group-toggle');
        if(toggle) toggle.setAttribute('aria-expanded','true');
      });
    }
  };
  faqGroups.forEach(group=>{
    const toggle=group.querySelector('.faq-group-toggle');
    if(!toggle)return;
    toggle.addEventListener('click',()=>{
      if(!faqGroupMedia.matches)return;
      const willOpen=!group.classList.contains('is-open');
      faqGroups.forEach(other=>setFaqGroupState(other,false));
      setFaqGroupState(group,willOpen);
      if(willOpen){
        requestAnimationFrame(()=>{
          const top=group.getBoundingClientRect().top;
          if(top<82) group.scrollIntoView({behavior:'smooth',block:'start'});
        });
      }
    });
  });
  syncFaqGroupMode();
  if(typeof faqGroupMedia.addEventListener==='function') faqGroupMedia.addEventListener('change',syncFaqGroupMode);
  else if(typeof faqGroupMedia.addListener==='function') faqGroupMedia.addListener(syncFaqGroupMode);
}
